. "$PSScriptRoot\Common.ps1"
function Register-CPAStackTasks([string]$RepoRoot) { $r=Get-CPAStackRoot; foreach($s in 'cli-proxy-api','cpa-usage-keeper'){ $file="Run-$($s -replace 'cli-proxy-api','CLIProxyAPI' -replace 'cpa-usage-keeper','UsageKeeper').ps1"; Copy-Item "$RepoRoot\windows\tasks\$file" "$r\tasks\$file" -Force; $n=Get-CPATaskName $s; $a=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -ExecutionPolicy Bypass -File `"$r\tasks\$file`""; $t=New-ScheduledTaskTrigger -AtStartup; $settings=New-ScheduledTaskSettingsSet -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -ExecutionTimeLimit (New-TimeSpan -Days 0); Register-ScheduledTask -TaskName $n -Action $a -Trigger $t -Settings $settings -User 'SYSTEM' -RunLevel Highest -Force|Out-Null} }
function Start-CPAStackService([string]$Service){$s=Resolve-CPAService $Service; Remove-Item (Join-Path (Get-CPAStackRoot) "state\$s.disabled") -Force -ErrorAction SilentlyContinue; Start-ScheduledTask -TaskName (Get-CPATaskName $s)}
function Stop-CPAStackService([string]$Service){$s=Resolve-CPAService $Service; New-Item -ItemType File -Force (Join-Path (Get-CPAStackRoot) "state\$s.disabled")|Out-Null; Stop-ScheduledTask -TaskName (Get-CPATaskName $s) -ErrorAction SilentlyContinue}
function Get-CPAStackServiceStatus([string]$Service){$s=Resolve-CPAService $Service; [pscustomobject]@{Service=$s;Task=(Get-ScheduledTask -TaskName (Get-CPATaskName $s)).State;Disabled=(Test-Path (Join-Path (Get-CPAStackRoot) "state\$s.disabled"));Version=(Split-Path ((Get-Item (Join-Path (Get-CPAStackRoot) "current\$s")).Target) -Leaf)}}
